        val row = ROWS[code]
        if (row[0] <= SENTINEL / 2.0) return SENTINEL   // no breast-height curve
        val x = ((si.coerceIn(GRID_MIN, GRID_MAX) - GRID_MIN) / STEP)
        val lo = x.toInt().coerceIn(0, NODES - 1)
        val hi = (lo + 1).coerceAtMost(NODES - 1)
        val frac = x - lo
        val v0 = row[lo]; val v1 = row[hi]
        if (v0 <= SENTINEL / 2.0 || v1 <= SENTINEL / 2.0) return SENTINEL
        return v0 + (v1 - v0) * frac
